/** Reveals content once while respecting reduced-motion preferences. */
export function Reveal({ children, className = '', delay = 0 }: Readonly<{
  children: ReactNode;
  className?: string;
  delay?: number;
}>) {
  const reduced = useQuietMotion();
  return (
    <motion.div
      className={`reveal-stage ${className}`}
      data-ambient="true"
      initial={reduced ? false : { opacity: 0, y: 30, scale: .985 }}
      whileInView={{ opacity: 1, y: 0, scale: 1 }}
      viewport={{ once: true, amount: .08 }}
      transition={{ duration: .65, delay, ease: [.22, 1, .36, 1] }}
    >
      {children}
    </motion.div>
  );
}

