/** Adds mouse-only movement without changing keyboard or reduced-motion behavior. */
function MagneticLink({ children, href, className = '' }: Readonly<{
  children: ReactNode;
  href: string;
  className?: string;
}>) {
  const x = useSpring(0, { stiffness: 300, damping: 25 });
  const y = useSpring(0, { stiffness: 300, damping: 25 });
  const reduced = useQuietMotion();
  return (
    <motion.a
      href={href}
      className={className}
      style={{ x, y }}
      onPointerMove={e => {
        if (reduced || e.pointerType !== 'mouse') {
          return;
        }
        const rect = e.currentTarget.getBoundingClientRect();
        x.set((e.clientX - rect.left - rect.width / 2) * .075);
        y.set((e.clientY - rect.top - rect.height / 2) * .12);
      }}
      onPointerLeave={() => {
        x.set(0);
        y.set(0);
      }}
      onBlur={() => {
        x.set(0);
        y.set(0);
      }}
    >
      {children}
    </motion.a>
  );
}

/** Tracks the active section and preserves keyboard access to mobile navigation. */
function Navbar({ paused, onToggleMotion }: Readonly<{ paused: boolean; onToggleMotion: () => void }>) {
  const [active, setActive] = useState('home');
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const menuButton = useRef<HTMLButtonElement>(null);
  const mobileMenu = useRef<HTMLElement>(null);
  const reduced = useReducedMotion();
  useEffect(() => {
    /** Selects the last navigation section that has crossed the active threshold. */
    const update = () => {
      setScrolled(window.scrollY > 20);
      const ids = Array.from(document.querySelectorAll<HTMLElement>('main section[id]')).map(section => section.id);
      ids.reverse();
      const selected = ids.find(id => (
        document.getElementById(id)?.getBoundingClientRect().top ?? Infinity
      ) <= 180);
      if (selected) {
        setActive(selected);
      }
    };
    let tick = 0;
    /** Coalesces scroll updates into a single animation frame. */
    const onScroll = () => {
      if (!tick) {
        tick = requestAnimationFrame(() => {
          update();
          tick = 0;
        });
      }
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    update();
    /** Closes the mobile navigation when switching to the desktop layout. */
    const resize = () => {
      if (window.innerWidth > 1000) {
        setOpen(false);
      }
    };
    window.addEventListener('resize', resize);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(tick);
    };
  }, []);
  useEffect(() => {
    if (!open) {
      return;
    }
    /** Restores focus to the menu toggle when Escape dismisses navigation. */
    const escape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setOpen(false);
        menuButton.current?.focus();
      }
    };
    /** Dismisses navigation only for pointer events outside the menu and toggle. */
    const outside = (e: PointerEvent) => {
      if (
        !mobileMenu.current?.contains(e.target as Node)
        && !menuButton.current?.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    window.addEventListener('keydown', escape);
    window.addEventListener('pointerdown', outside);
    return () => {
      window.removeEventListener('keydown', escape);
      window.removeEventListener('pointerdown', outside);
    };
  }, [open]);
  return (
    <header className={`site-header ${scrolled ? 'is-scrolled' : ''}`}>
      <div className="nav-shell">
        <a href="#home" className="brand" aria-label="Shilpa Gupta home">
          shilpa<span>.</span><span className="brand-last">gupta</span>
        </a>
        <nav className="desktop-nav" aria-label="Main navigation">
          {navigation.map(n => (
            <a
              key={n.id}
              href={`#${n.id}`}
              aria-current={active === n.id ? 'location' : undefined}
            >
              {n.label}
            </a>
          ))}
        </nav>
        <a className="nav-contact" href="#contact">
          Let’s talk <ArrowUpRight size={16} />
        </a>
        <button className="motion-toggle icon-button" aria-label={paused ? 'Play ambient animations' : 'Pause ambient animations'} aria-pressed={paused} onClick={onToggleMotion} disabled={!!reduced} title={reduced ? 'Reduced motion is enabled on your device' : 'Control ambient animation'}>
          {paused || reduced ? <Play size={17} /> : <Pause size={17} />}
        </button>
        <button
          ref={menuButton}
          className="menu-toggle icon-button"
          aria-label={open ? 'Close navigation' : 'Open navigation'}
          aria-expanded={open}
          aria-controls="mobile-navigation"
          onClick={() => setOpen(!open)}
        >
          {open ? <X /> : <Menu />}
        </button>
      </div>
      <AnimatePresence>
        {open && (
          <motion.nav
            ref={mobileMenu}
            id="mobile-navigation"
            className="mobile-nav"
            aria-label="Mobile navigation"
            initial={{ opacity: 0, y: reduced ? 0 : -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: reduced ? 0 : -8 }}
          >
            {navigation.map((n, i) => (
              <a
                href={`#${n.id}`}
                key={n.id}
                aria-current={active === n.id ? 'location' : undefined}
                onClick={() => {
                  setOpen(false);
                  document.getElementById(n.id)?.focus({ preventScroll: true });
                }}
              >
                <span>{String(i + 1).padStart(2, '0')}</span>{n.label}<ArrowUpRight size={17} />
              </a>
            ))}
          </motion.nav>
        )}
      </AnimatePresence>
    </header>
  );
}

