/** Keeps the success message ahead of the failure fallback, matching copy state priority. */
function getCopyStatus(copied: boolean, copyFailed: boolean): string {
  if (copied) {
    return 'Email copied to clipboard.';
  }
  if (copyFailed) {
    return 'Please select the email address to copy it.';
  }
  return '';
}

